'') ?>" aria-describedby="uuid-note"><small id="uuid-note">Capturarlo no valida el comprobante ante el SAT.</small></label><label class="admin-field"><span>Subtotal MXN</span><input name="subtotal" inputmode="decimal" required value="<?= e($invoice['subtotal']??'') ?>" placeholder="0.0000"></label><label class="admin-field"><span>Impuestos MXN</span><input name="tax_amount" inputmode="decimal" required value="<?= e($invoice['tax_amount']??'') ?>" placeholder="0.0000"></label><label class="admin-field"><span>Total MXN</span><input name="total" inputmode="decimal" required value="<?= e($invoice['total']??'') ?>" placeholder="0.0000"></label></div><label class="admin-field"><span>Observaciones</span><textarea name="notes" maxlength="1000"><?= e($invoice['notes']??'') ?></textarea></label><div class="admin-head-actions"><button class="admin-primary-button"><?= $editing?'Guardar cambios':'Guardar borrador' ?></button><a class="admin-secondary-button" href="<?= e($back) ?>">Cancelar</a></div></form><?php endif?>
